public static int countCommon(int[] a, int[] b) {
    int i = 0;
    int j = 0;
    int count = 0;
    while (i < a.length && j < b.length) {
        if (a[i] == b[j]) {
            count++;
            i++;
            j++;
        } else if (a[i] < b[j]) {
            i++;
        } else {
            j++;
        }
    }
    return count;
}

givenCode.code:
public static String check(Object got, Object expected) {
    String g = String.valueOf(got);
    if (got instanceof int[]) {
        g = java.util.Arrays.toString((int[]) got);
    }
    String e = String.valueOf(expected);
    if (g.equals(e)) {
        return "נכון";
    }
    return "לא נכון — התקבל " + g + ", צריך להתקבל " + e;
}

exercise.mainCode:
int[] a = { 2, 5, 9 };
int[] b = { 1, 4, 7, 10 };
System.out.println("סעיף א, בדיקה 1: " + check(merge(a, b), "[1, 2, 4, 5, 7, 9, 10]"));
System.out.println("סעיף א, בדיקה 2: " + check(merge(b, new int[0]), "[1, 4, 7, 10]"));
System.out.println("סעיף א, בדיקה 3: " + check(merge(new int[] { 3, 3 }, new int[] { 3 }), "[3, 3, 3]"));
int[] c = { 1, 3, 5, 8 };
int[] d = { 2, 3, 8, 9, 11 };
System.out.println("סעיף ב, בדיקה 1: " + check(countCommon(c, d), 2));
System.out.println("סעיף ב, בדיקה 2: " + check(countCommon(a, b), 0));
System.out.println("סעיף ב, בדיקה 3: " + check(countCommon(c, c), 4));

